use std::{env,fs,process::ExitCode};use vxn_core::{parser,Runtime,Value};
fn main()->ExitCode{let Some(path)=env::args().nth(1)else{eprintln!("usage: vxn-cli <program.vxn>");return ExitCode::from(2)};let source=match fs::read_to_string(&path){Ok(v)=>v,Err(e)=>{eprintln!("cannot read {path}: {e}");return ExitCode::from(1)}};let p=match parser::parse(&source){Ok(v)=>v,Err(e)=>{eprintln!("{e}");return ExitCode::from(1)}};match Runtime::default().execute(&p){Ok(r)=>{for v in r.output{match v{Value::Int(x)=>println!("{x}"),Value::Bool(x)=>println!("{x}"),Value::Text(x)=>println!("{x}"),Value::Unit=>println!("()")}}ExitCode::SUCCESS},Err(e)=>{eprintln!("{e}");ExitCode::from(1)}}}
